#!/usr/bin/env node
/**
 * Reconcile TWO independently completed human review sheets.
 *
 * node scripts/finalize-reader-contrast-review.mjs
 *   --reviewer-a PersonA --reviewer-b PersonB
 *
 * Optional --a PATH and --b PATH override the default local TSV filenames.
 * Requires the PRIVATE, gitignored answer key generated by preparer.
 * Never auto-relables GUM or feeds reviewed items into training.
 */
import {readFile,writeFile,access,mkdir} from "node:fs/promises";
import path from "node:path";
import {fileURLToPath} from "node:url";
import {VERSION,parseReviewSheet,reconcileReviews,adjudicationSheet}
 from "./reader-contrast-review-core.mjs";

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");
const local=n=>path.join(ROOT,"evaluation",n);
const DEFAULT={
 key:local("reader-contrast-review-key-v1.json"),
 a:local("reader-contrast-reviewer-a-v1.tsv"),
 b:local("reader-contrast-reviewer-b-v1.tsv"),
 output:local("reader-contrast-review-reconciled-v1.json"),
 disputes:local("reader-contrast-review-disagreements-v1.tsv")
};
export function args(argv){
 let a=DEFAULT.a,b=DEFAULT.b,reviewerA="",reviewerB="";
 for(let i=0;i<argv.length;i++){
  const arg=argv[i];
  if(arg==="--help"||arg==="-h"){
   console.log("node scripts/finalize-reader-contrast-review.mjs "+
    "--reviewer-a IDENTIFIER --reviewer-b OTHER_IDENTIFIER "+
    "[--a PATH] [--b PATH]");
   process.exit(0);
  }
  if(!["--reviewer-a","--reviewer-b","--a","--b"].includes(arg))
   throw Error("Unknown option "+arg);
  const v=argv[++i];
  if(!v)throw Error("Missing value for "+arg);
  if(arg==="--reviewer-a")reviewerA=v.trim();
  if(arg==="--reviewer-b")reviewerB=v.trim();
  if(arg==="--a")a=path.resolve(v);
  if(arg==="--b")b=path.resolve(v);
 }
 if(!reviewerA||!reviewerB||
  reviewerA.toLowerCase()===reviewerB.toLowerCase())
  throw Error("Two distinct reviewer identifiers are required");
 if(a===b)throw Error("A and B cannot be the same review file");
 return {a,b,reviewerA,reviewerB};
}
async function main(){
 const o=args(process.argv.slice(2));
 const [key,rawA,rawB]=await Promise.all([
  readFile(DEFAULT.key,"utf8").then(JSON.parse),
  readFile(o.a,"utf8"),readFile(o.b,"utf8")
 ]);
 if(key.version!==VERSION||key.count!==48)
  throw Error("Unexpected private review key");
 const reviewedA=parseReviewSheet(rawA,key,"A"),
  reviewedB=parseReviewSheet(rawB,key,"B");
 const outcome=reconcileReviews(key,reviewedA,reviewedB);
 // Reviewer IDs are used only to confirm that two DIFFERENT people worked
 // independently; their personally identifying strings are not exported.
 outcome.reviewerCount=2;
 outcome.reviewerIdentityPolicy="Distinct pseudonyms supplied; not retained";
 for(const output of [DEFAULT.output,DEFAULT.disputes]){
  try{await access(output);throw Error(
   "Refusing to overwrite prior human review result "+output);}
  catch(e){if(e.code!=="ENOENT")throw e;}
 }
 await mkdir(path.dirname(DEFAULT.output),{recursive:true});
 await Promise.all([
  writeFile(DEFAULT.output,JSON.stringify(outcome,null,2)+"\n"),
  writeFile(DEFAULT.disputes,adjudicationSheet(key,reviewedA,reviewedB))
 ]);
 const pct=n=>(100*n).toFixed(1)+"%";
 console.log("Two-reviewer contrast interpretation study");
 console.log("  Reviewed "+outcome.sampled+" real sentence pairs");
 console.log("  Exactly agreeing "+outcome.agreementCount+"/"+
  outcome.sampled+" ("+pct(outcome.agreementRate)+")");
 console.log("  Cohen kappa "+outcome.cohenKappa.toFixed(3));
 console.log("  Usable (two matching, non-uncertain) "+
  outcome.usableConsensus);
 console.log("  Both AND and BUT reasonable "+
  (outcome.consensusLabels.both??0)+"/"+outcome.usableConsensus);
 console.log("  GDTB compatible "+outcome.gdtbCompatibleInConsensus+
  "/"+outcome.usableConsensus);
 console.log("  Model compatible "+outcome.modelCompatibleInConsensus+
  "/"+outcome.usableConsensus);
 console.log("  By hidden stratum: "+JSON.stringify(outcome.byStratum));
 console.log("  Numeric source-free report: "+DEFAULT.output);
 console.log("  Private human disagreement sheet: "+DEFAULT.disputes);
 console.log("No human labels have been added to classifier training.");
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))
 main().catch(e=>{console.error(e?.stack||e);process.exitCode=1;});
